questionvariables.text:
/* Fixed: one specific proof. Options in a fixed order, the best summary second. */
optsS: [
 [smexp, false, "Multiply out \\(n(n + 1)(n + 2)\\) to get \\(n^3 + 3n^2 + 2n\\), and show that this expression has a factor of 6 for every positive integer \\(n\\)."],
 [smpar, true, "Among any three consecutive integers at least one is even and one is a multiple of 3, so the product is a multiple of 2 and of 3, and therefore of 6."],
 [smemp, false, "Check that \\(1 \\times 2 \\times 3 = 6\\), \\(2 \\times 3 \\times 4 = 24\\) and \\(3 \\times 4 \\times 5 = 60\\) are all multiples of 6, and conclude that every such product is a multiple of 6."],
 [smsix, false, "Among any three consecutive integers one of them is always a multiple of 6, so their product must also be a multiple of 6."]
];
